package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.SortOrder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class DefaultKeyedValues_removeValue_TriageGen2Test {

    private DefaultKeyedValues dataset;

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_LastItemNoRebuild() {
        // Setup: Add two items
        dataset.addValue("A", 1.0);
        dataset.addValue("B", 2.0);

        // Remove the last item (index 1)
        // According to logic: index (1) is NOT < keys.size() (which becomes 1 after remove)
        // Therefore, rebuildIndex() should not be triggered (branch coverage)
        dataset.removeValue(1);

        assertEquals(1, dataset.getItemCount());
        assertEquals("A", dataset.getKey(0));
        assertEquals(1.0, dataset.getValue(0).doubleValue(), 0.001);
    }

    @Test
    public void testRemoveValue_MiddleItemTriggersRebuild() {
        // Setup: Add three items
        dataset.addValue("A", 1.0);
        dataset.addValue("B", 2.0);
        dataset.addValue("C", 3.0);

        // Remove the first item (index 0)
        // index (0) < keys.size() (which becomes 2 after remove)
        // Therefore, rebuildIndex() is triggered (branch coverage)
        dataset.removeValue(0);

        assertEquals(2, dataset.getItemCount());
        assertEquals("B", dataset.getKey(0));
        assertEquals(2.0, dataset.getValue(0).doubleValue(), 0.001);
        assertEquals("C", dataset.getKey(1));
        assertEquals(3.0, dataset.getValue(1).doubleValue(), 0.001);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveValue_InvalidIndex() {
        // Setup
        dataset.addValue("A", 1.0);

        // Attempt to remove an index that doesn't exist
        // This tests the behavior of the underlying List.remove(int)
        dataset.removeValue(5);
    }

    @Test
    public void testRemoveValue_EmptyDataset() {
        // Attempting to remove from empty dataset should throw exception 
        // based on standard List behavior used in the method
        try {
            dataset.removeValue(0);
        } catch (IndexOutOfBoundsException e) {
            // Expected behavior for index 0 in empty list
        }
    }

    @Test
    public void testRemoveValue_SingleItem() {
        dataset.addValue("A", 1.0);

        // Remove the only item
        // index (0) is NOT < keys.size() (which becomes 0)
        dataset.removeValue(0);

        assertEquals(0, dataset.getItemCount());
    }
}
